// Generated by APP-002; preserved verbatim for qualitative evaluation.
export type UserContext = Record<string, any>;

export type ConditionOperator = 'equals' | 'notEquals' | 'in';

export interface Condition {
  field: string;
  operator: ConditionOperator;
  value: any;
}

export interface Rule {
  priority: number;
  value: boolean;
  conditions: Condition[];
}

export interface FeatureFlag {
  defaultValue: boolean;
  rules: Rule[];
}

export class FeatureFlagEvaluator {
  private static validateCondition(condition: Condition): void {
    if (!condition.field || !condition.operator || !condition.value) {
      throw new Error('Malformed condition');
    }

    if (!['equals', 'notEquals', 'in'].includes(condition.operator)) {
      throw new Error(`Unknown operator: ${condition.operator}`);
    }

    if (condition.operator === 'in' && !Array.isArray(condition.value)) {
      throw new Error('In operator requires an array value');
    }
  }

  private static validateRule(rule: Rule): void {
    if (!Number.isFinite(rule.priority)) {
      throw new Error('Priority must be a finite number');
    }

    if (rule.conditions.length === 0) {
      throw new Error('Rule must have at least one condition');
    }

    for (const condition of rule.conditions) {
      this.validateCondition(condition);
    }
  }

  private static validateFeatureFlag(flag: FeatureFlag): void {
    if (typeof flag.defaultValue !== 'boolean') {
      throw new Error('Default value must be a boolean');
    }

    for (const rule of flag.rules) {
      this.validateRule(rule);
    }
  }

  static evaluate(flag: FeatureFlag, context: UserContext): boolean {
    this.validateFeatureFlag(flag);

    const sortedRules = [...flag.rules].sort((a, b) => {
      if (a.priority !== b.priority) {
        return a.priority - b.priority;
      }
      return 0;
    });

    for (const rule of sortedRules) {
      let matches = true;

      for (const condition of rule.conditions) {
        const field = condition.field;
        const operator = condition.operator;
        const value = condition.value;
        const contextValue = context[field];

        if (contextValue === undefined) {
          matches = false;
          break;
        }

        switch (operator) {
          case 'equals':
            if (!Object.is(contextValue, value)) {
              matches = false;
              break;
            }
            break;
          case 'notEquals':
            if (Object.is(contextValue, value)) {
              matches = false;
              break;
            }
            break;
          case 'in':
            if (!Array.isArray(value) || !value.includes(contextValue, 0)) {
              matches = false;
              break;
            }
            break;
        }
      }

      if (matches) {
        return rule.value;
      }
    }

    return flag.defaultValue;
  }
}
